import os
def count_py(d):
    n = 0
    for name in os.listdir(d):
        if name.endswith('.py'):
            n += 1
    return n
print(count_py(os.getcwd()))

import math
def hyp(a, b):
    return math.sqrt(a * a + b * b)
print(hyp(3, 4), math.floor(2.7), math.ceil(2.1), math.gcd(12, 18))

import functools
@functools.lru_cache(maxsize=None)
def fib(n):
    return n if n < 2 else fib(n - 1) + fib(n - 2)
print(fib(20), functools.reduce(lambda a, b: a + b, [1, 2, 3]))

